class Solution:
    def countDigits(self, num: int) -> int:
        ans, n = 0, num
        while n > 0:
            d = n % 10
            if num % d == 0:
                ans += 1
            n //= 10
        return ans

c.cpp:
class Solution {
public:
    int countDigits(int num) {
        int ans = 0;
        for (int n = num; n > 0; n /= 10)
            if (num % (n % 10) == 0) ans++;
        return ans;
    }
};

